4T20:08:08.882214+00:00","category":"accesorio","subcategory":"accesorio","life_stage":null,"requires_confirmation":false},"brand":{"id":"aa2a28f1-2b5d-4526-b895-e8027a817dd7","name":"VITA","client_id":"1d2d79c4-19e0-4a6d-83f1-cf714ee7618b"},"presentations":[{"id":"f0e98152-3a02-4ee3-874e-03a982d9b202","price":4800,"stock":null,"active":true,"weight":"125gr","currency":"COP","metadata":{"llave":"1075","codigo":"10601011075","source":"productos.json","codigos":["10601011075"],"nombre_original":"VITA PICHONES 125GR"},"created_at":"2026-06-04T20:08:09.045554+00:00","sort_order":0,"updated_at":"2026-06-04T20:08:09.045554+00:00","reference_id":"8bac1dcc-4a3e-4faf-8429-c098f3eac94e"}]}]'::jsonb)
 AS x(id uuid,before_row jsonb,after_row jsonb,brand jsonb,presentations jsonb);
-- Bloqueo determinista; FOR UPDATE de padre impide insertar variantes concurrentemente.
SELECT b.id FROM public.catalog_brands b WHERE b.id IN (SELECT (brand->>'id')::uuid FROM classification_apply) ORDER BY b.id FOR SHARE;
SELECT r.id FROM public.catalog_references r JOIN classification_apply p ON p.id=r.id ORDER BY r.id FOR UPDATE OF r;
SELECT v.id FROM public.catalog_presentations v JOIN classification_apply p ON p.id=v.reference_id ORDER BY v.id FOR UPDATE OF v;
DO $classification$
DECLARE n integer;
BEGIN
 IF (SELECT count(*) FROM classification_apply) <> 374 THEN RAISE EXCEPTION 'Conteo de plan incorrecto'; END IF;
 IF (SELECT count(*) FROM public.aivance_clients WHERE id='1d2d79c4-19e0-4a6d-83f1-cf714ee7618b'::uuid AND slug='distrifinca') <> 1 THEN RAISE EXCEPTION 'Tenant incorrecto'; END IF;
 IF EXISTS (SELECT 1 FROM classification_apply p LEFT JOIN public.catalog_references r ON r.id=p.id LEFT JOIN public.catalog_brands b ON b.id=r.brand_id
   WHERE r.id IS NULL OR b.client_id IS DISTINCT FROM '1d2d79c4-19e0-4a6d-83f1-cf714ee7618b'::uuid
   OR jsonb_build_object('id',b.id,'client_id',b.client_id,'name',b.name) IS DISTINCT FROM p.brand
   OR to_jsonb(r) IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.before_row)))
 THEN RAISE EXCEPTION 'Referencia/tenant/estado previo divergente: cancelar y volver a auditar'; END IF;
 IF EXISTS (SELECT 1 FROM classification_apply p WHERE
  COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.catalog_presentations v WHERE v.reference_id=p.id),'[]'::jsonb)
  IS DISTINCT FROM COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM jsonb_populate_recordset(NULL::public.catalog_presentations,p.presentations) v),'[]'::jsonb))
 THEN RAISE EXCEPTION 'Presentaciones divergentes: no sobrescribir datos concurrentes'; END IF;
 IF EXISTS (SELECT 1 FROM classification_apply WHERE before_row - ARRAY['species','category','subcategory','life_stage','updated_at','metadata']
   IS DISTINCT FROM after_row - ARRAY['species','category','subcategory','life_stage','updated_at','metadata']
   OR (before_row->'metadata')-'especies' IS DISTINCT FROM (after_row->'metadata')-'especies')
 THEN RAISE EXCEPTION 'Plan modifica campos protegidos'; END IF;
 UPDATE public.catalog_references r SET
   species=p.after_row->>'species', category=p.after_row->>'category',
   subcategory=p.after_row->>'subcategory', life_stage=p.after_row->>'life_stage', metadata=p.after_row->'metadata'
 FROM classification_apply p WHERE r.id=p.id
   AND to_jsonb(r)=to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.before_row));
 GET DIAGNOSTICS n = ROW_COUNT;
 IF n <> 374 THEN RAISE EXCEPTION 'Conteo actualizado incorrecto: %',n; END IF;
 IF EXISTS (SELECT 1 FROM classification_apply p JOIN public.catalog_references r ON r.id=p.id
   WHERE to_jsonb(r)-'updated_at' IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.after_row))-'updated_at')
 THEN RAISE EXCEPTION 'Verificación posterior de campos falló'; END IF;
 IF EXISTS (SELECT 1 FROM classification_apply p WHERE
  COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.catalog_presentations v WHERE v.reference_id=p.id),'[]'::jsonb)
  IS DISTINCT FROM COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM jsonb_populate_recordset(NULL::public.catalog_presentations,p.presentations) v),'[]'::jsonb))
 THEN RAISE EXCEPTION 'Se alteraron presentaciones: cancelar'; END IF;
 -- Retener imagen posterior real, incluido updated_at, para reversión segura.
 UPDATE classification_apply p SET after_row=to_jsonb(r) FROM public.catalog_references r WHERE r.id=p.id;
END $classification$;
COMMIT;
SELECT count(*) AS referencias_verificadas FROM classification_apply;
-- GUARDAR la celda rollback_sql completa. Es la reversión ejecutable con timestamps reales.
-- La reversión abortará si cualquiera de las referencias o sus presentaciones cambió después.
SELECT count(*) AS referencias_verificadas,
 jsonb_agg(jsonb_build_object('id',id,'nombre',after_row->>'name','especie',after_row->>'species',
 'categoria',after_row->>'category','subcategoria',after_row->>'subcategory','etapa',after_row->>'life_stage',
 'especies_declaradas',after_row->'metadata'->'especies','updated_at',after_row->>'updated_at') ORDER BY id) AS lectura_posterior,
 replace($rollback_template$-- VERSION: clasificacion-20261028-r4
-- Distrifinca: revisión puntual de clasificación. Sin cambios de esquema/RLS.
-- Ejecutar completo en SQL Editor con rol autorizado. Ante error: ROLLBACK; no eliminar guardas.
-- Un cambio concurrente incluso en precio, stock o updated_at aborta todo el lote.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
CREATE TEMP TABLE classification_undo (id uuid PRIMARY KEY,before_row jsonb NOT NULL,after_row jsonb NOT NULL,brand jsonb NOT NULL,presentations jsonb NOT NULL) ON COMMIT PRESERVE ROWS;
INSERT INTO classification_undo SELECT * FROM jsonb_to_recordset(__PAYLOAD_LITERAL__::jsonb)
 AS x(id uuid,before_row jsonb,after_row jsonb,brand jsonb,presentations jsonb);
-- Bloqueo determinista; FOR UPDATE de padre impide insertar variantes concurrentemente.
SELECT b.id FROM public.catalog_brands b WHERE b.id IN (SELECT (brand->>'id')::uuid FROM classification_undo) ORDER BY b.id FOR SHARE;
SELECT r.id FROM public.catalog_references r JOIN classification_undo p ON p.id=r.id ORDER BY r.id FOR UPDATE OF r;
SELECT v.id FROM public.catalog_presentations v JOIN classification_undo p ON p.id=v.reference_id ORDER BY v.id FOR UPDATE OF v;
DO $classification$
DECLARE n integer;
BEGIN
 IF (SELECT count(*) FROM classification_undo) <> 374 THEN RAISE EXCEPTION 'Conteo de plan incorrecto'; END IF;
 IF (SELECT count(*) FROM public.aivance_clients WHERE id='1d2d79c4-19e0-4a6d-83f1-cf714ee7618b'::uuid AND slug='distrifinca') <> 1 THEN RAISE EXCEPTION 'Tenant incorrecto'; END IF;
 IF EXISTS (SELECT 1 FROM classification_undo p LEFT JOIN public.catalog_references r ON r.id=p.id LEFT JOIN public.catalog_brands b ON b.id=r.brand_id
   WHERE r.id IS NULL OR b.client_id IS DISTINCT FROM '1d2d79c4-19e0-4a6d-83f1-cf714ee7618b'::uuid
   OR jsonb_build_object('id',b.id,'client_id',b.client_id,'name',b.name) IS DISTINCT FROM p.brand
   OR to_jsonb(r) IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.before_row)))
 THEN RAISE EXCEPTION 'Referencia/tenant/estado previo divergente: cancelar y volver a auditar'; END IF;
 IF EXISTS (SELECT 1 FROM classification_undo p WHERE
  COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.catalog_presentations v WHERE v.reference_id=p.id),'[]'::jsonb)
  IS DISTINCT FROM COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM jsonb_populate_recordset(NULL::public.catalog_presentations,p.presentations) v),'[]'::jsonb))
 THEN RAISE EXCEPTION 'Presentaciones divergentes: no sobrescribir datos concurrentes'; END IF;
 IF EXISTS (SELECT 1 FROM classification_undo WHERE before_row - ARRAY['species','category','subcategory','life_stage','updated_at','metadata']
   IS DISTINCT FROM after_row - ARRAY['species','category','subcategory','life_stage','updated_at','metadata']
   OR (before_row->'metadata')-'especies' IS DISTINCT FROM (after_row->'metadata')-'especies')
 THEN RAISE EXCEPTION 'Plan modifica campos protegidos'; END IF;
 UPDATE public.catalog_references r SET
   species=p.after_row->>'species', category=p.after_row->>'category',
   subcategory=p.after_row->>'subcategory', life_stage=p.after_row->>'life_stage', metadata=p.after_row->'metadata'
 FROM classification_undo p WHERE r.id=p.id
   AND to_jsonb(r)=to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.before_row));
 GET DIAGNOSTICS n = ROW_COUNT;
 IF n <> 374 THEN RAISE EXCEPTION 'Conteo actualizado incorrecto: %',n; END IF;
 IF EXISTS (SELECT 1 FROM classification_undo p JOIN public.catalog_references r ON r.id=p.id
   WHERE to_jsonb(r)-'updated_at' IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::public.catalog_references,p.after_row))-'updated_at')
 THEN RAISE EXCEPTION 'Verificación posterior de campos falló'; END IF;
 IF EXISTS (SELECT 1 FROM classification_undo p WHERE
  COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.catalog_presentations v WHERE v.reference_id=p.id),'[]'::jsonb)
  IS DISTINCT FROM COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM jsonb_populate_recordset(NULL::public.catalog_presentations,p.presentations) v),'[]'::jsonb))
 THEN RAISE EXCEPTION 'Se alteraron presentaciones: cancelar'; END IF;
 -- Retener imagen posterior real, incluido updated_at, para reversión segura.
 UPDATE classification_undo p SET after_row=to_jsonb(r) FROM public.catalog_references r WHERE r.id=p.id;
END $classification$;
COMMIT;
SELECT count(*) AS referencias_verificadas FROM classification_undo;
$rollback_template$, '__PAYLOAD_LITERAL__',
 quote_literal(jsonb_agg(jsonb_build_object('id',id,'before_row',after_row,'after_row',before_row,'brand',brand,'presentations',presentations) ORDER BY id)::text)) AS rollback_sql
FROM classification_apply;
